const digestSites = `-- name: DigestSites :many
SELECT i.id, i.label, i.connected_at, coalesce(u.name, '')::text AS connected_by_name,
       s.address, s.site_url, s.name, s.plugin_version, s.feed_url, s.categories, s.last_report_at, s.rule_enabled, s.rule
FROM integrations i
JOIN wordpress_sites s ON s.integration_id = i.id
LEFT JOIN users u ON u.id = i.connected_by
WHERE i.workspace_id = $1 AND i.kind = 'wordpress' AND i.disconnected_at IS NULL
ORDER BY i.connected_at, i.id
`

type DigestSitesRow struct {
	ID              uuid.UUID       `json:"id"`
	Label           string          `json:"label"`
	ConnectedAt     time.Time       `json:"connectedAt"`
	ConnectedByName string          `json:"connectedByName"`
	Address         string          `json:"address"`
	SiteUrl         string          `json:"siteUrl"`
	Name            string          `json:"name"`
	PluginVersion   string          `json:"pluginVersion"`
	FeedUrl         string          `json:"feedUrl"`
	Categories      json.RawMessage `json:"categories"`
	LastReportAt    *time.Time      `json:"lastReportAt"`
	RuleEnabled     bool            `json:"ruleEnabled"`
	Rule            json.RawMessage `json:"rule"`
}

// The workspace's connected WordPress sites, as feed sources.
func (q *Queries) DigestSites(ctx context.Context, workspaceID uuid.UUID) ([]DigestSitesRow, error) {
	rows, err := q.db.Query(ctx, digestSites, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DigestSitesRow{}
	for rows.Next() {
		var i DigestSitesRow
		if err := rows.Scan(
			&i.ID,
			&i.Label,
			&i.ConnectedAt,
			&i.ConnectedByName,
			&i.Address,
			&i.SiteUrl,
			&i.Name,
			&i.PluginVersion,
			&i.FeedUrl,
			&i.Categories,
			&i.LastReportAt,
			&i.RuleEnabled,
			&i.Rule,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

