const digestUsedItems = `-- name: DigestUsedItems :many
SELECT DISTINCT ii.item_id FROM digest_issue_items ii JOIN digest_issues i ON i.id = ii.issue_id
WHERE i.digest_id = $1 AND i.status IN ('sending', 'sent')
`

// Items already sent in an issue of the digest: they aren't new any more.
func (q *Queries) DigestUsedItems(ctx context.Context, digestID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, digestUsedItems, digestID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var item_id uuid.UUID
		if err := rows.Scan(&item_id); err != nil {
			return nil, err
		}
		items = append(items, item_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const digestsActive = `-- name: DigestsActive :many
SELECT d.id, d.workspace_id, d.name, d.template_id, d.state, d.mode, d.source, d.feed_url, d.site_id, d.categories, d.tags, d.max_age_days, d.start_mode, d.start_latest, d.schedule, d.prepare_hours, d.late_hours, d.archive, d.owner_id, d.owner_since, d.first_on_at, d.paused_at, d.paused_by, d.pause_reason, d.pause_note, d.pause_detail, d.feed_skips, d.feed_status, d.feed_kind, d.feed_title, d.feed_items, d.feed_bytes, d.feed_etag, d.feed_modified, d.feed_error, d.feed_snippet, d.feed_moved_to, d.last_read_at, d.last_read_via, d.last_ok_at, d.created_by, d.created_at, d.updated_by, d.updated_at, d.deleted_at FROM digests d
JOIN workspaces w ON w.id = d.workspace_id AND w.deleted_at IS NULL
WHERE d.deleted_at IS NULL
  AND (d.state = 'on' OR EXISTS (SELECT 1 FROM digest_issues i WHERE i.digest_id = d.id AND i.status IN ('preparing', 'prepared', 'held', 'draft', 'sending')))
ORDER BY d.id
`

// Digests the minute job looks after: on, or paused with an issue still
// sending or waiting to be settled.
func (q *Queries) DigestsActive(ctx context.Context) ([]Digest, error) {
	rows, err := q.db.Query(ctx, digestsActive)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Digest{}
	for rows.Next() {
		var i Digest
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Name,
			&i.TemplateID,
			&i.State,
			&i.Mode,
			&i.Source,
			&i.FeedUrl,
			&i.SiteID,
			&i.Categories,
			&i.Tags,
			&i.MaxAgeDays,
			&i.StartMode,
			&i.StartLatest,
			&i.Schedule,
			&i.PrepareHours,
			&i.LateHours,
			&i.Archive,
			&i.OwnerID,
			&i.OwnerSince,
			&i.FirstOnAt,
			&i.PausedAt,
			&i.PausedBy,
			&i.PauseReason,
			&i.PauseNote,
			&i.PauseDetail,
			&i.FeedSkips,
			&i.FeedStatus,
			&i.FeedKind,
			&i.FeedTitle,
			&i.FeedItems,
			&i.FeedBytes,
			&i.FeedEtag,
			&i.FeedModified,
			&i.FeedError,
			&i.FeedSnippet,
			&i.FeedMovedTo,
			&i.LastReadAt,
			&i.LastReadVia,
			&i.LastOkAt,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedBy,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

